begin;
insert into public.ce_course2_resources(id,data) values
('course2_module3_pdf','{"base64": "", "sha256": "aee3aeae77c52d6c8e988b0a90e75f0e2b5871c2605becb8412bc918223aa810", "filename": "CE_HALO_Course2_Module03_Pheochromocytoma_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course2_module3_questions','[{"module_id": "course_2_module_3", "question_id": "course_2_module_3_q01", "question_number": 1, "stem": "Which biochemical test is recommended by the Endocrine Society as first-line screening for pheochromocytoma in a high-risk patient (e.g., known hereditary syndrome or prior PPGL)? ]", "choice_a": "Plasma free (fractionated) metanephrines", "choice_b": "Serum chromogranin A alone", "choice_c": "Serum catecholamines drawn during a symptom-free period", "choice_d": "24-hour urinary vanillylmandelic acid (VMA)", "correct_choice": "a", "rationale": "Plasma free (fractionated) metanephrines have sensitivity 96–99% and are the recommended first-line screening test in high-risk patients per the Endocrine Society guideline (Lenders et al., 2014). 24-hour urinary fractionated metanephrines are the alternative first-line test in lower-risk screening. VMA and chromogranin A alone are not first-line.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q02", "question_number": 2, "stem": "Which of the following is the correct sequence for preoperative pharmacologic optimization of a patient with pheochromocytoma? ]", "choice_a": "Simultaneous alpha and beta blockade with immediate surgery", "choice_b": "Alpha blockade first, then volume loading, then beta blockade if needed", "choice_c": "Metyrosine alone, no alpha or beta blockade", "choice_d": "Beta blockade first, then alpha blockade, then volume loading", "correct_choice": "b", "rationale": "Alpha blockade must precede beta blockade. Starting beta blockade before alpha blockade removes vasodilating beta-2 activity while alpha-mediated vasoconstriction persists, producing catastrophic unopposed vasoconstriction. Volume loading follows alpha blockade to correct chronic hypovolemia.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q03", "question_number": 3, "stem": "Which finding from the PRESCRIPT randomized trial (Buitenwerf et al., 2020) best summarizes the phenoxybenzamine-versus-doxazosin comparison? ]", "choice_a": "Doxazosin produced significantly lower perioperative mortality than phenoxybenzamine", "choice_b": "The two drugs produced identical hemodynamic profiles", "choice_c": "Phenoxybenzamine produced fewer intraoperative hypertensive episodes; doxazosin produced fewer postoperative hypotensive episodes; no difference in mortality or major cardiovascular events", "choice_d": "Phenoxybenzamine produced significantly lower perioperative mortality than doxazosin", "correct_choice": "c", "rationale": "The PRESCRIPT trial (Buitenwerf 2020) found phenoxybenzamine yielded fewer intraoperative hypertensive episodes (a consequence of noncompetitive long-acting blockade) but more postoperative hypotension; doxazosin produced fewer postoperative hypotensive episodes. Mortality, MI, stroke, and ICU LOS were not different. Both agents are acceptable.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q04", "question_number": 4, "stem": "A patient with pheochromocytoma has completed 12 days of phenoxybenzamine 40 mg BID. Which set of findings best meets the Roizen criteria for preoperative readiness? ]", "choice_a": "BP 178/98 seated; new ST-T changes on ECG yesterday; 12 PVCs/min", "choice_b": "BP <120/80 with severe orthostasis to 70/40 on standing", "choice_c": "BP <165/90 but bradycardia to 42 bpm at rest", "choice_d": "BP <165/90 seated for 24–48 h; mild orthostasis; ECG stable for ≥1 week; <5 PVCs/min", "correct_choice": "d", "rationale": "Roizen criteria: BP <165/90 seated for 24–48 hours, mild orthostasis only, no ST-T changes for ≥1 week, and <5 PVCs/min. Severe orthostasis or bradycardia indicates overshoot; residual hypertension with ECG changes indicates inadequate preparation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q05", "question_number": 5, "stem": "Which drug is contraindicated (or should be avoided) in a patient with an inadequately alpha-blocked pheochromocytoma? ]", "choice_a": "Isolated beta blockade (e.g., metoprolol without alpha blockade)", "choice_b": "Sodium nitroprusside", "choice_c": "Clevidipine", "choice_d": "Nicardipine", "correct_choice": "a", "rationale": "Isolated beta blockade removes vasodilating beta-2 activity while alpha-mediated vasoconstriction is unopposed, causing hypertensive crisis, LV failure, and pulmonary edema. Nicardipine, clevidipine, and sodium nitroprusside are all appropriate for controlling hypertension in the pheochromocytoma patient.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q06", "question_number": 6, "stem": "During adrenal vein ligation, which drug should the CRNA have drawn, labeled, and immediately available even before evidence of hypotension? ]", "choice_a": "Metoclopramide", "choice_b": "Vasopressin", "choice_c": "Additional volatile anesthetic", "choice_d": "Large-dose morphine bolus", "correct_choice": "b", "rationale": "Vasopressin is particularly effective in the catecholamine-resistant vasoplegia that can follow adrenal vein ligation. It should always be prepared and labeled before this transition. Morphine (histamine release) and metoclopramide (dopamine antagonism) are problematic in pheochromocytoma.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q07", "question_number": 7, "stem": "Which intraoperative event most often triggers a severe catecholamine surge during laparoscopic adrenalectomy for pheochromocytoma? ]", "choice_a": "Skin closure", "choice_b": "Antibiotic administration", "choice_c": "Tumor compression or mobilization and abdominal insufflation", "choice_d": "Emergence from anesthesia", "correct_choice": "c", "rationale": "The most dramatic hypertensive episodes occur during intubation, abdominal insufflation, incision, and direct tumor compression or mobilization. Adrenal vein ligation is the pivot point for the opposite problem — sudden hypotension.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q08", "question_number": 8, "stem": "A patient develops profound hypotension (MAP 45) 5 minutes after adrenal vein ligation. Which initial pharmacologic response is most appropriate? ]", "choice_a": "Continue vasodilator infusion at current rate", "choice_b": "Bolus phenoxybenzamine to deepen alpha blockade", "choice_c": "Metoprolol IV to slow reflex tachycardia", "choice_d": "Norepinephrine infusion titrated to MAP goal, with vasopressin and fluid available; consider phenylephrine boluses", "correct_choice": "d", "rationale": "Post-resection hypotension is multifactorial (catecholamine withdrawal, residual alpha blockade, anesthetic vasodilation, chronic hypovolemia). First-line management is norepinephrine infusion titrated to MAP goal, with vasopressin available for catecholamine-resistant vasoplegia and judicious fluid resuscitation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q09", "question_number": 9, "stem": "During an elective cholecystectomy, BP acutely rises to 260/150 with new pulmonary edema at insufflation in a patient with no known pheochromocytoma history. Which is NOT part of the CRNA immediate-action bundle? ]", "choice_a": "Immediately administer metoprolol 5 mg IV as isolated therapy", "choice_b": "Deepen anesthesia and ask the surgeon to pause", "choice_c": "Start a short-acting antihypertensive (nicardipine, clevidipine, or phentolamine)", "choice_d": "Consider aborting the elective operation once stable and arranging endocrine workup", "correct_choice": "a", "rationale": "Isolated beta blockade in a patient with a suspected undiagnosed pheochromocytoma (never alpha-blocked) is dangerous — it can worsen vasoconstriction. Deepening anesthesia, short-acting vasodilators, magnesium adjunct, surgeon pause, and consideration of aborting the elective case are all appropriate.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q10", "question_number": 10, "stem": "Approximately what proportion of pheochromocytoma and paraganglioma cases in modern series are found to carry an identifiable germline mutation on multi-gene panel testing? ]", "choice_a": "About 1%", "choice_b": "About 30–40%", "choice_c": "About 80%", "choice_d": "About 10%", "correct_choice": "b", "rationale": "Contemporary series using multi-gene panel sequencing find identifiable germline mutations in 30–40% of PPGL patients — substantially higher than the older \"10% familial\" teaching. Every PPGL patient should be offered genetic evaluation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q11", "question_number": 11, "stem": "Which hereditary PPGL syndrome carries the highest risk of metastatic disease and often prompts consideration of systemic therapy such as belzutifan? ]", "choice_a": "Neurofibromatosis type 1 (NF1)", "choice_b": "Von Hippel-Lindau (VHL)", "choice_c": "SDHB paraganglioma syndrome", "choice_d": "MEN2A (RET mutation)", "correct_choice": "c", "rationale": "SDHB-mutated paragangliomas carry the highest metastatic risk (up to ~40%) and are the most likely to require long-term surveillance and systemic therapy for advanced disease. MEN2, VHL, and NF1 are associated with PPGL but with different clinical patterns and lower metastatic risk.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q12", "question_number": 12, "stem": "Why does chronic pheochromocytoma often produce intravascular volume contraction despite hypertension? ]", "choice_a": "Excess catecholamines directly deplete plasma volume via renal excretion of albumin", "choice_b": "Catecholamines cause primary aldosterone deficiency", "choice_c": "Chronic hyperglycemia causes osmotic diuresis and hypovolemia", "choice_d": "Sustained alpha-1 vasoconstriction elevates blood pressure, the kidney responds with pressure diuresis, and the circulating volume falls", "correct_choice": "d", "rationale": "Sustained alpha-1 vasoconstriction elevates blood pressure; the kidney responds with pressure diuresis, reducing intravascular volume 10–20% below normal over months to years. This contracted volume becomes clinically apparent when alpha blockade is instituted or when catecholamines fall at adrenal vein ligation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q13", "question_number": 13, "stem": "Which of the following BEST describes the role of magnesium sulfate in pheochromocytoma anesthesia? ]", "choice_a": "Adjunct that reduces catecholamine release, blunts arrhythmia, provides mild vasodilation, and potentiates neuromuscular blockade", "choice_b": "First-line vasopressor for post-resection hypotension", "choice_c": "Contraindicated in pheochromocytoma", "choice_d": "Diagnostic agent to confirm biochemical pheochromocytoma", "correct_choice": "a", "rationale": "Magnesium sulfate is a valuable adjunct in pheochromocytoma anesthesia — it reduces catecholamine release from chromaffin cells and adrenergic nerves, blunts arrhythmia, provides mild vasodilation, and potentiates neuromuscular blockade (reduce NMBA dose and monitor TOF).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q14", "question_number": 14, "stem": "Which drug should be prepared and labeled specifically because adrenal vein ligation may be followed by catecholamine-resistant vasoplegia unresponsive to conventional adrenergic vasopressors? ]", "choice_a": "Dopamine", "choice_b": "Vasopressin", "choice_c": "Milrinone", "choice_d": "Metoprolol", "correct_choice": "b", "rationale": "Vasopressin is non-adrenergic and effective when adrenergic responsiveness is blunted after tumor resection. Metoprolol worsens hemodynamics; dopamine may provoke arrhythmia; milrinone would worsen vasodilation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q15", "question_number": 15, "stem": "Which finding in the immediate postoperative period after pheochromocytoma resection is common enough to warrant scheduled monitoring for at least 24 hours? ]", "choice_a": "Hyperkalemia", "choice_b": "Malignant hyperthermia", "choice_c": "Rebound hypoglycemia from catecholamine withdrawal and restored insulin secretion", "choice_d": "Immediate return of hypertension in every patient", "correct_choice": "c", "rationale": "Catecholamine excess inhibits insulin secretion and raises glucose. After tumor resection, insulin rebounds and hypoglycemia can be significant. Scheduled glucose monitoring every 1–2 hours for at least 24 h is standard, with special attention in diabetic patients.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q16", "question_number": 16, "stem": "Which set of induction and airway drugs is generally considered safe in an ADEQUATELY prepared pheochromocytoma patient? ]", "choice_a": "Ketamine (high dose), ephedrine, succinylcholine, morphine 50 mg bolus", "choice_b": "Metoclopramide induction followed by isolated beta blockade", "choice_c": "Cocaine topical + high-dose morphine", "choice_d": "Propofol, fentanyl, rocuronium, sevoflurane", "correct_choice": "d", "rationale": "Propofol, fentanyl, rocuronium, and a volatile such as sevoflurane are all appropriate in an optimized patient. High-dose ketamine, ephedrine, succinylcholine (fasciculations may compress the tumor), and large morphine boluses (histamine) are best avoided or used cautiously. Metoclopramide has case reports of provoking hypertensive crisis.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q17", "question_number": 17, "stem": "Which imaging modality is preferred for a suspected PPGL in pregnancy or when iodinated contrast should be avoided? ]", "choice_a": "MRI abdomen (T2-weighted)", "choice_b": "Barium enema", "choice_c": "Contrast-enhanced CT abdomen/pelvis", "choice_d": "Bone scan", "correct_choice": "a", "rationale": "MRI (typically T2-weighted) is preferred in pregnancy, pediatric patients, contrast allergy, and head-and-neck paragangliomas. Contrast-enhanced CT is first-line in most adults with confirmed biochemistry.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q18", "question_number": 18, "stem": "Metyrosine (α-methyl-para-tyrosine) works by: ]", "choice_a": "Activating vasopressin V1 receptors", "choice_b": "Inhibiting tyrosine hydroxylase, thereby reducing catecholamine synthesis", "choice_c": "Antagonizing dopamine at D2 receptors", "choice_d": "Blocking alpha-1 adrenergic receptors", "correct_choice": "b", "rationale": "Metyrosine inhibits tyrosine hydroxylase, the rate-limiting enzyme in catecholamine synthesis. Its use signals a high-burden case (very large tumor, extensive metastatic disease, or refractory symptoms). Sedation and crystalluria are the main dose-limiting side effects.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q19", "question_number": 19, "stem": "A CRNA is caring for a patient on chronic belzutifan therapy for metastatic paraganglioma who now presents for elective cholecystectomy. Which perioperative consideration is most specific to belzutifan? ]", "choice_a": "Contraindication to all volatile anesthetics", "choice_b": "Need for prophylactic anticoagulation", "choice_c": "Anemia (up to 90% of patients on belzutifan) — assess hemoglobin, plan for possible transfusion, consider oxygen-delivery reserve", "choice_d": "Significant risk of malignant hyperthermia", "correct_choice": "c", "rationale": "Belzutifan (HIF-2α inhibitor, U.S. FDA approval May 2025) causes anemia in up to 90% of patients (grade 3+ in ~20%). Preoperative hemoglobin assessment and transfusion planning are the key perioperative considerations. It does not cause MH, contraindicate volatile agents, or mandate anticoagulation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q20", "question_number": 20, "stem": "Which sequence best reflects the phase-specific transitions the CRNA should anticipate during laparoscopic pheochromocytoma resection? ]", "choice_a": "Skin closure → emergence → PACU pain control", "choice_b": "Regional block → sedation → local infiltration", "choice_c": "Antibiotic administration → warming blanket → OG tube → foley", "choice_d": "Induction and intubation → insufflation → tumor manipulation → adrenal vein ligation → post-resection hypotension", "correct_choice": "d", "rationale": "The intraoperative course of pheochromocytoma resection is best understood as a series of predictable transitions: induction/intubation → insufflation → tumor manipulation → adrenal vein ligation → post-resection hypotension. The CRNA prepares the appropriate drug before each transition.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q21", "question_number": 21, "stem": "Which vasopressor is often selected as first-line INFUSION for post-resection hypotension in the pheochromocytoma patient? ]", "choice_a": "Norepinephrine (0.02–0.5 mcg/kg/min)", "choice_b": "Dopamine at 20 mcg/kg/min", "choice_c": "Isoproterenol", "choice_d": "Milrinone alone", "correct_choice": "a", "rationale": "Norepinephrine is the usual first-line infusion for post-resection vasodilatory hypotension because it provides strong vasopressor support with some beta-1 activity for cardiac output. Phenylephrine boluses and vasopressin infusion are complementary options.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q22", "question_number": 22, "stem": "Which of the following adrenal masses REQUIRES biochemical exclusion of pheochromocytoma BEFORE any biopsy, surgical resection, or adrenal manipulation? ]", "choice_a": "Only masses in patients over 65 years old", "choice_b": "Every adrenal incidentaloma identified on cross-sectional imaging", "choice_c": "Only masses greater than 10 cm", "choice_d": "Only masses in patients with known cancer elsewhere", "correct_choice": "b", "rationale": "Approximately 5–10% of adrenal incidentalomas are pheochromocytomas. Biopsy or surgical manipulation of an unsuspected pheochromocytoma has been described as producing life-threatening catecholamine crisis. Every adrenal incidentaloma requires biochemical exclusion before intervention.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q23", "question_number": 23, "stem": "Roizen criteria include which of the following? ]", "choice_a": "BP consistently >180/110 for 24 hours", "choice_b": "Complete absence of any orthostatic change", "choice_c": "BP <165/90 seated for 24–48 h, mild orthostasis only, no ST-T changes for ≥1 week, <5 PVCs/min", "choice_d": "Ability to run one mile without symptoms", "correct_choice": "c", "rationale": "The Roizen criteria are pragmatic clinical endpoints of adequate preoperative preparation: BP <165/90 seated for 24–48 hours, mild orthostasis only, no ST-T changes for ≥1 week, and <5 PVCs/min. They are not hard cutoffs but guide the decision to proceed with elective surgery.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q24", "question_number": 24, "stem": "A patient with a paraganglioma is on doxazosin. During tumor manipulation, BP rises to 235/125 despite an infusion of nicardipine. Which additional agent is a reasonable next choice for this DISCRETE catecholamine-driven spike? ]", "choice_a": "Additional oral doxazosin", "choice_b": "Ephedrine bolus", "choice_c": "Metoclopramide", "choice_d": "Phentolamine 2–5 mg IV bolus", "correct_choice": "d", "rationale": "Phentolamine provides acute alpha-adrenergic blockade and is particularly useful for discrete catecholamine-driven spikes during tumor handling. Anticipate hypotension once the stimulation stops. Additional oral doxazosin acts too slowly; ephedrine and metoclopramide are contraindicated/inappropriate.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_3", "question_id": "course_2_module_3_q25", "question_number": 25, "stem": "After pheochromocytoma resection, biochemical cure should be confirmed by: ]", "choice_a": "Plasma or urinary metanephrines rechecked 2–6 weeks postoperatively, then annual lifelong surveillance", "choice_b": "A negative CT scan at 24 hours", "choice_c": "A single normal in-hospital blood pressure", "choice_d": "Discharge without vasopressor requirement", "correct_choice": "a", "rationale": "Biochemical cure is confirmed by plasma or urinary metanephrines 2–6 weeks after surgery. Because up to 15% of patients (higher for hereditary or SDHB disease) develop recurrence or metastatic disease, the Endocrine Society guideline recommends lifelong annual biochemical surveillance.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course2_resources where id='course2_module3_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course2_catalog where id='1047241'),'Course must remain staged';
end $$;
commit;